# GCU400 has 48 SPC per wave; a larger grid serializes in waves (see
# gcu400/ops/sum.py and batch_norm_stats.py for the same fixed-grid +
# in-kernel stride precedent).
MAX_GRID = 48
# Per-program on-chip budget (fp32 tiles plus accumulators).
DSM_BYTES = 448 * 1024
# Whole-channel hold cap: two fp32 tiles (x, grad_output) held across both
# passes, so the cap keeps them inside the DSM budget with headroom for the
# normalized-input and output tiles.
HOLD_TILE_MAX_ELEMENTS = 16384
# Hard ceiling for a 1D grid launch on this backend.
GRID_X_MAX = 65535


