@triton.jit
def cudnn_batch_norm_backward_hold_kernel(
    grad_output_pointer,
    input_pointer,
    weight_pointer,
    mean_pointer,
    invstd_pointer,
    input_grad_pointer,
    weight_grad_pointer,
    bias_grad_pointer,
    batch_dim,
    channel_dim,
    spatial_dim,
    inv_count,
    grad_output_batch_stride,
    grad_output_feat_stride,
    grad_output_spatial_stride,
    input_batch_stride,
    input_feat_stride,
    input_spatial_stride,
    input_grad_batch_stride,
    input_grad_feat_stride,
    input_grad_spatial_stride,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    NUM_STAGES: tl.constexpr,
):
    """Holdable-shape arm: one program per channel strided over the grid.

    The whole (batch, spatial) extent of the channel is loaded into two fp32
    tiles once; the reduction and the elementwise pass both reuse them, so
    traffic drops to 2R+1W. The tile loads are issued before the per-channel
    scalar loads (probe: scalar-first delays the tile issue by ~1 us per
    channel). Masked-off lanes contribute dy == 0 to both reductions, so no
    explicit where() is needed unless invstd is infinite, in which case the
    reference gradients are non-finite anyway.
    """
    pid = tl.program_id(0)
    for feat in tl.range(pid, channel_dim, tl.num_programs(0), num_stages=NUM_STAGES):
        batch_offset = tl.arange(0, BLOCK_M)
        spatial_offset = tl.arange(0, BLOCK_N)
        mask = (batch_offset[:, None] < batch_dim) & (
            spatial_offset[None, :] < spatial_dim
        )
        curr_grad_output = tl.load(
            grad_output_pointer
            + grad_output_feat_stride * feat
            + grad_output_batch_stride * batch_offset[:, None]
            + grad_output_spatial_stride * spatial_offset[None, :],
            mask=mask,
            other=0.0,
        ).to(tl.float32)
        curr_input = tl.load(
            input_pointer
            + input_feat_stride * feat
            + input_batch_stride * batch_offset[:, None]
            + input_spatial_stride * spatial_offset[None, :],
            mask=mask,
            other=0.0,
        ).to(tl.float32)
        mean = tl.load(mean_pointer + feat).to(tl.float32)
        inv_std = tl.load(invstd_pointer + feat).to(tl.float32)
        weight = tl.load(weight_pointer + feat).to(tl.float32)

        curr_norm = (curr_input - mean) * inv_std
        term1 = tl.sum(curr_norm * curr_grad_output)
        term2 = tl.sum(curr_grad_output)

        tl.store(
            weight_grad_pointer + feat,
            term1.to(weight_grad_pointer.dtype.element_ty),
        )
        tl.store(bias_grad_pointer + feat, term2.to(bias_grad_pointer.dtype.element_ty))

        input_grad_pointers = (
            input_grad_pointer
            + input_grad_feat_stride * feat
            + input_grad_batch_stride * batch_offset[:, None]
            + input_grad_spatial_stride * spatial_offset[None, :]
        )
        curr_input_grad = (
            inv_std
            * weight
            * (curr_grad_output - (term1 * curr_norm + term2) * inv_count)
        )
        tl.store(
            input_grad_pointers,
            curr_input_grad.to(input_grad_pointer.dtype.element_ty),
            mask=mask,
        )


@libentry()
@triton.jit
def cudnn_batch_norm_backward_partial_kernel(
    grad_output_pointer,
    input_pointer,
    mean_pointer,
    invstd_pointer,
    partials_pointer,
    batch_dim,
    channel_dim,
    spatial_dim,
    m_steps,
    n_steps,
    grad_output_batch_stride,
    grad_output_feat_stride,
    grad_output_spatial_stride,
    input_batch_stride,
    input_feat_stride,
    input_spatial_stride,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
):
    """Reduction stage over (channel, row-block) groups.

    Each group streams its rows of one channel through an affine spatial
    loop into two [BLOCK_N] vector accumulators -- the axis-0 tree per step
    keeps the live accumulator footprint small (probe: deferred [BLOCK_M,
    BLOCK_N] accumulators spill and halve the streaming rate) -- and the
    epilogue pays only two scalar tree calls per group, amortizing the
    backend's fixed ~1.6 us-per-call reduction cost across the whole group.
    """
    pid = tl.program_id(0)
    num_groups = channel_dim * m_steps
    # No num_stages here: pipelining the group loop multiplies the live tile
    # and accumulator state across its nested spatial loop and spills (probe:
    # 51 us vs 16 us for the same geometry with a plain group loop).
    for group in tl.range(pid, num_groups, tl.num_programs(0)):
        feat = group // m_steps
        m_step = group % m_steps
        mean = tl.load(mean_pointer + feat).to(tl.float32)
        inv_std = tl.load(invstd_pointer + feat).to(tl.float32)

        batch_offset = m_step * BLOCK_M + tl.arange(0, BLOCK_M)
        batch_mask = batch_offset < batch_dim
        term1_acc = tl.zeros([BLOCK_N], dtype=tl.float32)
        term2_acc = tl.zeros([BLOCK_N], dtype=tl.float32)
        for n_step in range(0, n_steps):
            spatial_offset = n_step * BLOCK_N + tl.arange(0, BLOCK_N)
            mask = batch_mask[:, None] & (spatial_offset < spatial_dim)[None, :]
            curr_grad_output = tl.load(
                grad_output_pointer
                + grad_output_feat_stride * feat
                + grad_output_batch_stride * batch_offset[:, None]
                + grad_output_spatial_stride * spatial_offset[None, :],
                mask=mask,
                other=0.0,
            ).to(tl.float32)
            curr_input = tl.load(
                input_pointer
                + input_feat_stride * feat
                + input_batch_stride * batch_offset[:, None]
                + input_spatial_stride * spatial_offset[None, :],
                mask=mask,
                other=0.0,
            ).to(tl.float32)
            curr_norm = (curr_input - mean) * inv_std
            term1_acc += tl.sum(curr_norm * curr_grad_output, axis=0)
            term2_acc += tl.sum(curr_grad_output, axis=0)
        term1 = tl.sum(term1_acc)
        term2 = tl.sum(term2_acc)
        tl.store(partials_pointer + group * 2, term1)
        tl.store(partials_pointer + group * 2 + 1, term2)


@libentry()
@triton.jit
def cudnn_batch_norm_backward_apply_kernel(
    grad_output_pointer,
    input_pointer,
    weight_pointer,
    mean_pointer,
    invstd_pointer,
    input_grad_pointer,
    weight_grad_pointer,
    bias_grad_pointer,
    partials_pointer,
    batch_dim,
    channel_dim,
    spatial_dim,
    m_steps,
    partials_m_steps,
    n_steps,
    inv_count,
    grad_output_batch_stride,
    grad_output_feat_stride,
    grad_output_spatial_stride,
    input_batch_stride,
    input_feat_stride,
    input_spatial_stride,
    input_grad_batch_stride,
    input_grad_feat_stride,
    input_grad_spatial_stride,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    M_BLOCK: tl.constexpr,
):
    """Combine-and-apply stage over its own (channel, row-block) groups.

    Each group first reduces its channel's [partials_m_steps] partial pairs
    into the final term1 / term2 scalars (two small trees), then streams its
    rows of grad_input through the affine spatial loop. The row-block 0
    group of each channel also emits the weight and bias gradients. The
    group geometry is independent of the partial stage's, so the apply
    tile shape can follow its own probe-swept optimum.
    """
    pid = tl.program_id(0)
    num_groups = channel_dim * m_steps
    for group in tl.range(pid, num_groups, tl.num_programs(0)):
        feat = group // m_steps
        m_step = group % m_steps

        partial_offsets = tl.arange(0, M_BLOCK)
        partial_mask = partial_offsets < partials_m_steps
        partial_base = (
            partials_pointer + (feat * partials_m_steps + partial_offsets) * 2
        )
        term1 = tl.sum(tl.load(partial_base, mask=partial_mask, other=0.0))
        term2 = tl.sum(tl.load(partial_base + 1, mask=partial_mask, other=0.0))

        if m_step == 0:
            tl.store(
                weight_grad_pointer + feat,
                term1.to(weight_grad_pointer.dtype.element_ty),
            )
            tl.store(
                bias_grad_pointer + feat,
                term2.to(bias_grad_pointer.dtype.element_ty),
            )

        mean = tl.load(mean_pointer + feat).to(tl.float32)
        inv_std = tl.load(invstd_pointer + feat).to(tl.float32)
        weight = tl.load(weight_pointer + feat).to(tl.float32)

        batch_offset = m_step * BLOCK_M + tl.arange(0, BLOCK_M)
        batch_mask = batch_offset < batch_dim
        for n_step in range(0, n_steps):
            spatial_offset = n_step * BLOCK_N + tl.arange(0, BLOCK_N)
            mask = batch_mask[:, None] & (spatial_offset < spatial_dim)[None, :]
            curr_grad_output = tl.load(
                grad_output_pointer
                + grad_output_feat_stride * feat
                + grad_output_batch_stride * batch_offset[:, None]
                + grad_output_spatial_stride * spatial_offset[None, :],
                mask=mask,
                other=0.0,
            ).to(tl.float32)
            curr_input = tl.load(
                input_pointer
                + input_feat_stride * feat
                + input_batch_stride * batch_offset[:, None]
                + input_spatial_stride * spatial_offset[None, :],
                mask=mask,
                other=0.0,
            ).to(tl.float32)
            curr_norm = (curr_input - mean) * inv_std
            curr_input_grad = (
                inv_std
                * weight
                * (curr_grad_output - (term1 * curr_norm + term2) * inv_count)
            )
            tl.store(
                input_grad_pointer
                + input_grad_feat_stride * feat
                + input_grad_batch_stride * batch_offset[:, None]
                + input_grad_spatial_stride * spatial_offset[None, :],
                curr_input_grad.to(input_grad_pointer.dtype.element_ty),
                mask=mask,
            )


def make_3d_for_bn(input: Tensor) -> Tensor:
    """
    Converts the input to a 3D view for batch normalization.

    Args:
        input: Input to render 3D.

    Returns:
        Input's 3D view.
    """
    if input.ndim == 2:
        input = input.unsqueeze(-1)

    elif input.ndim >= 4:
        input = input.flatten(2, -1)

    return input


def _partial_launch_config(batch_dim, channel_dim, spatial_dim):
    """Reduction-stage geometry: ~32 (channel, row-block) groups.

    Probe-swept: fewer, wider groups win -- each group pays a fixed
    tree-and-scalar cost, and the per-step axis-0 trees keep the live
    accumulators at [BLOCK_N], so 16K-element tiles with a 4096-wide
    spatial block maximize the streaming rate per group.
    """
    block_n = min(triton.next_power_of_2(spatial_dim), 4096)
    m_steps = 1
    if channel_dim < 32:
        m_steps = min(triton.next_power_of_2(batch_dim), max(1, 32 // channel_dim))
    block_m = triton.next_power_of_2(triton.cdiv(batch_dim, m_steps))
    block_m = min(block_m, max(1, 32768 // block_n))
    m_steps = triton.cdiv(batch_dim, block_m)
    n_steps = triton.cdiv(spatial_dim, block_n)
    return block_m, block_n, m_steps, n_steps


def _apply_launch_config(batch_dim, channel_dim, spatial_dim):
    """Apply-stage geometry, independent of the reduction stage.

    Probe-swept: wide spatial tiles win here (no accumulators to spill),
    with the row block shrinking only for the very wide spatial dims.
    """
    if spatial_dim >= 8192:
        block_n = min(triton.next_power_of_2(spatial_dim), 4096)
    else:
        block_n = min(triton.next_power_of_2(spatial_dim), 2048)
    block_m = min(triton.next_power_of_2(batch_dim), max(1, 32768 // block_n))
    m_steps = triton.cdiv(batch_dim, block_m)
    n_steps = triton.cdiv(spatial_dim, block_n)
    return block_m, block_n, m_steps, n_steps


def _validate_backward(input, grad_output, weight, save_mean, save_var):
    if input.ndim < 2 or input.ndim > 5 or input.numel() == 0:
        raise RuntimeError(
            "cudnn_batch_norm_backward requires a nonempty rank 2 through 5 input"
        )
    if (
        grad_output.shape != input.shape
        or grad_output.dtype != input.dtype
        or grad_output.device != input.device
    ):
        raise RuntimeError("grad_output must match input shape, dtype and device")
    param_dtype = torch.float32 if input.dtype == torch.float16 else input.dtype
    if input.dtype not in (torch.float16, torch.float32, torch.float64):
        raise RuntimeError("unsupported cudnn_batch_norm_backward input dtype")
    for t in (weight, save_mean, save_var):
        if (
            t is None
            or t.numel() != input.shape[1]
            or t.dtype != param_dtype
            or t.device != input.device
            or not t.is_contiguous()
        ):
            raise RuntimeError(
                "weight and saved statistics must be contiguous C-element tensors with the parameter dtype"
            )


def cudnn_batch_norm_backward(
    input: Tensor,
    grad_output: Tensor,
    weight: Tensor,
    running_mean: Tensor = None,
    running_var: Tensor = None,
    save_mean: Tensor = None,
    save_var: Tensor = None,
    epsilon: float = 1e-5,
    reserveSpace: Tensor = None,
):
    logger.debug("GEMS_ENFLAME CUDNN_BATCH_NORM_BACKWARD")
    _validate_backward(input, grad_output, weight, save_mean, save_var)

    input_3d = make_3d_for_bn(input)
    grad_output_3d = make_3d_for_bn(grad_output)

    batch_dim, feat_dim, spatial_dim = input_3d.shape

    # Always compute all gradients
    input_grad = torch.empty_like(input_3d)
    weight_grad = torch.empty_like(weight)
    bias_grad = torch.empty_like(weight)

    # Precomputed on the host: a kernel-side (batch_dim * spatial_dim) cast
    # breaks when triton specializes batch_dim == 1 into a python int.
    inv_count = 1.0 / float(batch_dim * spatial_dim)

    with torch_device_fn.device(input.device):
        hold_m = triton.next_power_of_2(batch_dim)
        hold_n = triton.next_power_of_2(spatial_dim)
        holdable = hold_m * hold_n <= HOLD_TILE_MAX_ELEMENTS
        if holdable:
            # One pass of loads feeds both the reduction and the elementwise
            # update (2R+1W instead of 3R+1W traffic), so every holdable
            # shape prefers this arm regardless of the element count.
            assert (
                hold_m * hold_n * 4 * 4 <= DSM_BYTES
            ), "hold kernel tile exceeds the DSM budget"
            cudnn_batch_norm_backward_hold_kernel[(min(MAX_GRID, feat_dim),)](
                grad_output_3d,
                input_3d,
                weight,
                save_mean,
                save_var,
                input_grad,
                weight_grad,
                bias_grad,
                batch_dim,
                feat_dim,
                spatial_dim,
                inv_count,
                *grad_output_3d.stride(),
                *input_3d.stride(),
                *input_grad.stride(),
                BLOCK_M=hold_m,
                BLOCK_N=hold_n,
                NUM_STAGES=2,
                num_warps=2,
            )
        else:
            (
                block_m,
                block_n,
                m_steps,
                n_steps,
            ) = _partial_launch_config(batch_dim, feat_dim, spatial_dim)
            apply_m, apply_n, apply_m_steps, apply_n_steps = _apply_launch_config(
                batch_dim, feat_dim, spatial_dim
            )
            assert (
                block_m * block_n * 4 * 3 <= DSM_BYTES
            ), "partial tile exceeds the DSM budget"
            assert (
                apply_m * apply_n * 4 * 3 <= DSM_BYTES
            ), "apply tile exceeds the DSM budget"
            num_groups = feat_dim * m_steps
            grid = (min(num_groups, GRID_X_MAX),)
            # [channel, m_steps, 2] fp32 staging buffer.
            partials = torch.empty(
                2 * num_groups, dtype=torch.float32, device=input_3d.device
            )
            cudnn_batch_norm_backward_partial_kernel[grid](
                grad_output_3d,
                input_3d,
                save_mean,
                save_var,
                partials,
                batch_dim,
                feat_dim,
                spatial_dim,
                m_steps,
                n_steps,
                *grad_output_3d.stride(),
                *input_3d.stride(),
                BLOCK_M=block_m,
                BLOCK_N=block_n,
                num_warps=4,
            )
            apply_grid = (min(feat_dim * apply_m_steps, GRID_X_MAX),)
            cudnn_batch_norm_backward_apply_kernel[apply_grid](
                grad_output_3d,
                input_3d,
                weight,
                save_mean,
                save_var,
                input_grad,
                weight_grad,
                bias_grad,
                partials,
                batch_dim,
                feat_dim,
                spatial_dim,
                apply_m_steps,
                m_steps,
                apply_n_steps,
                inv_count,
                *grad_output_3d.stride(),
                *input_3d.stride(),
                *input_grad.stride(),
                BLOCK_M=apply_m,
                BLOCK_N=apply_n,
                M_BLOCK=triton.next_power_of_2(m_steps),
                num_warps=4,
            )

    return (
        input_grad.view_as(input),
        weight_grad,
        bias_grad,
    )
